/* stresstest comparison report — static UI.
 *
 * Reads window.REPORT_DATA (populated by data.js — regenerated by
 * `make stresstest`) and renders the page. Edit freely and refresh the
 * browser; no test rerun required.
 *
 * Page structure:
 *  Heatmap section: scenario rows × protocol columns colored by the
 *  p2p_normal-sweep success rate (production-shaped baseline). Clicking
 *  any cell opens a modal dialog with a tab bar to flip between sweeps;
 *  each tab shows a CDF (single-point sweep) or a P99 trend line
 *  (multi-point sweep) for the selected scenario × all protocols.
 */

'use strict';

// Protocol series colors — used for chart lines, dataset point markers,
// and the modal's per-protocol summary line. Picked with similar
// saturation/lightness so the protocols read as peers rather than
// figure/ground.
const PROTOCOL_COLORS = {
  OBFT:        '#ed8936', // light orange
  '2abOBFT':   '#06b6d4', // cyan
  QBFT:        '#e85a71', // light pink-red (computed-RT variant)
  'QBFT-SSV':  '#8b5cf6', // purple (production-RT variant)
};

// SLOT_END_MS is the spec's relay cutoff (the 4 s proposer-duty
// deadline). Right edge of the CDF x-axis, pinned regardless of
// slot_start — the chart axis is absolute slot time.
const SLOT_END_MS = 4000;

// SLOT_STARTS is the set of "operator joins at" offsets the picker
// offers. The chart x-axis is absolute slot time; cdfSlotStartPlugin
// draws a dashed marker at slot_start showing where in the slot the
// operator became available.
//   QBFT: pipeline runs slot_start later, so sample x = decide_time +
//     slot_start; sample fails when it overflows SLOT_END_MS.
//   OBFT / 2abOBFT: broadcast schedule is slot-anchored, so sample x =
//     T_k_broadcast (unchanged); sample fails when T_k_broadcast <
//     slot_start (operator missed the deciding layer's broadcast).
const SLOT_STARTS = [0, 400, 800, 1200, 1600, 2000, 2400, 2800];

// selectedSlotStart is shared module state across every sweep tab.
// User picks via the slot_start picker; the value persists when
// switching between tabs (staggered slot-start should be comparable
// across baselines + the multi-point sweeps).
let selectedSlotStart = 0;

// selectedTrendMetric controls the y-axis on multi-point trend charts:
//   'success' — per-point success rate (0..1), bounded y-axis with
//      red/yellow/green zone bands.
//   'p99'     — per-point p99 of (shifted) decision times in ms, free
//      y-axis with no zones.
// Module-level only because the legacy modal still uses it. Each
// collapsible chart owns its own copy in `collapsibleState` so they
// can be toggled independently.
let selectedTrendMetric = 'success';

// selectedScenario drives the "Normal operations" chart at the top of
// the page (the previously modal-tabbed CDF chart, now always-visible).
// Heatmap row click updates this; the chart re-renders for the new
// scenario at the picker-chosen (K, BTT, σ, slot_start).
//
// Default is "Healthy" — the all-honest baseline scenario whose Title
// is "Normal operations (all-honest healthy path)".
let selectedScenario = 'Healthy';

// Picker dimensions for the Normal operations chart. Phase 1 (no
// regen yet) constrains buttons to the values backed by existing data:
//   K ∈ {data-derived}; BTT ∈ {data-derived}; σ ∈ {data-derived}
// Phase 2 will widen these via the new p2pBaselineSweep cross-product
// (K ∈ {3,4}, BTT ∈ {100..500ms}, σ ∈ {0.1, 0.3, 0.5, 0.7}).
let selectedK = 4;
let selectedBTT = 300;
let selectedSigma = 0.5;

// collapsibleState[sweepName] = { expanded: bool, metric: 'success'|'p99', slotStart: int }
// Per-section state for the collapsible sweep charts (Increasing BTT,
// Heavy-tail propagation, Stochastic loss, Correlated link delays,
// Correlated node slowness). Each has its OWN pickers independent of
// the page-level ones, so the user can compare different operating
// points across the four collapsibles without rebinding global state.
const collapsibleState = {};

// cdfZonesPlugin paints three horizontal bands keyed to the y-axis:
// red ≤ 90%, yellow 90–99%, green 99–100%. Used by both chart families
// (single-point CDF + multi-point trend) — both now plot success rate
// on the y-axis, so the same zone semantics apply. Tints are kept light
// (low saturation × low alpha) so the bands read as background, not as
// data.
const cdfZonesPlugin = {
  id: 'cdfZones',
  beforeDatasetsDraw(chart) {
    const { ctx, chartArea, scales } = chart;
    const y = scales.y;
    if (!y) return;
    const zones = [
      { from: 0, to: 0.9, color: 'hsla(0, 70%, 75%, 0.06)' },
      { from: 0.9, to: 0.99, color: 'hsla(50, 90%, 60%, 0.06)' },
      { from: 0.99, to: 1.0, color: 'hsla(130, 55%, 60%, 0.09)' },
    ];
    ctx.save();
    zones.forEach((z) => {
      const yTop = y.getPixelForValue(z.to);
      const yBottom = y.getPixelForValue(z.from);
      ctx.fillStyle = z.color;
      ctx.fillRect(chartArea.left, yTop, chartArea.right - chartArea.left, yBottom - yTop);
    });
    ctx.restore();
  },
};

// cdfSlotStartPlugin shades the left-side band [0, slot_start] — time
// the operator wasn't present in the slot yet — and draws a dashed
// vertical line at slot_start. No-op when slot_start = 0 (operator
// joined at slot start, nothing to mark).
const cdfSlotStartPlugin = {
  id: 'cdfSlotStart',
  beforeDatasetsDraw(chart) {
    if (selectedSlotStart === 0) return;
    const { ctx, chartArea, scales } = chart;
    const x = scales.x;
    if (!x) return;
    const xStart = x.getPixelForValue(selectedSlotStart);
    if (xStart <= chartArea.left) return;
    ctx.save();
    ctx.fillStyle = 'rgba(15, 23, 42, 0.05)';
    ctx.fillRect(chartArea.left, chartArea.top, xStart - chartArea.left, chartArea.bottom - chartArea.top);
    ctx.strokeStyle = 'rgba(15, 23, 42, 0.3)';
    ctx.setLineDash([4, 3]);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(xStart, chartArea.top);
    ctx.lineTo(xStart, chartArea.bottom);
    ctx.stroke();
    ctx.restore();
  },
};

document.addEventListener('DOMContentLoaded', main);

function main() {
  const data = window.REPORT_DATA;
  const root = document.getElementById('root');
  if (!data) {
    return; // index.html already shows the placeholder.
  }
  applyChartDefaults();
  // One-time precompute of slot_start variants for every single-point
  // sweep cell. Cached on the cell itself as `cell.slotShifts[slotStart]`
  // → shifted cell view. Subsequent reads (heatmap render on slot
  // change, conditions chart rebuild, legend stats) are O(1) lookups.
  precomputeSlotShifts(data);
  // Initialize selectedSigma / selectedBTT / selectedK to whichever
  // values the loaded data actually has (Phase 1: single-value lookup
  // against p2p_normal). Phase 2's baseline sweep will widen each
  // picker's button set.
  initBaselineSelections(data);
  root.innerHTML = '';
  const mainEl = h('main');
  // Page layout (top → bottom):
  //   1. Normal operations chart — the always-visible CDF that used
  //      to live in the modal. Pickers (K, BTT, σ, slot_start) drive
  //      both this chart and the heatmap's cell colors.
  //   2. Heatmap — colored by the same pickers; row click updates the
  //      Normal operations chart's selected scenario.
  //   3. Collapsibles — Increasing BTT, Heavy-tail propagation,
  //      Stochastic loss, Correlated link delays, Correlated node
  //      slowness. Each has its own local pickers + y-axis toggle.
  mainEl.appendChild(renderConditionsSection(data));
  const overview = renderHeatmap(data);
  if (overview) mainEl.appendChild(overview);
  mainEl.appendChild(renderCollapsibles(data));
  root.appendChild(mainEl);
}

// initBaselineSelections snaps selectedK/selectedBTT/selectedSigma to
// values actually present in the loaded data, so the Normal operations
// chart can render on first load even when data was generated against
// an earlier sweep config than the current UI expects.
function initBaselineSelections(data) {
  const sweep = data.sweeps.find((s) => s.name === 'p2p_normal') ||
                data.sweeps.find((s) => s.name === 'p2p_ideal');
  if (!sweep || sweep.points.length === 0) return;
  const cfg = sweep.points[0].config && sweep.points[0].config.Base;
  if (cfg) {
    if (typeof cfg.K === 'number' && cfg.K > 0) selectedK = cfg.K;
    if (typeof cfg.BTT === 'number') selectedBTT = Math.round(cfg.BTT / 1e6);
  }
  // σ is read from sweep params (e.g. "LogNormal σ=0.5"); fall through
  // to default 0.5 when the sweep doesn't expose it explicitly.
  const sigmaParam = (sweep.params || []).find((p) => /σ\s*=/.test(p));
  if (sigmaParam) {
    const m = /σ\s*=\s*(\d+(?:\.\d+)?)/.exec(sigmaParam);
    if (m) selectedSigma = parseFloat(m[1]);
  }
}

// precomputeSlotShifts warms shiftedCell's cache for the heatmap's
// single-point sweep so the first slot_start change doesn't trigger a
// burst of shift computations under the click. Multi-point sweeps are
// left to lazy-compute on first chart render (cheap; ≤ 18 cells per
// chart). Cells with no samples (n/a, 0%) are skipped — nothing to
// shift.
function precomputeSlotShifts(data) {
  data.sweeps.forEach((sweep) => {
    if (sweep.points.length !== 1) return;
    sweep.points[0].cells.forEach((cell) => {
      if (!cell.decisionTimes || cell.decisionTimes.length === 0) return;
      for (let i = 1; i < SLOT_STARTS.length; i++) {
        shiftedCell(cell, SLOT_STARTS[i]);
      }
    });
  });
}

// shiftedCell returns a slot-start-adjusted view of `cell`, lazily
// computing + caching the result on `cell.slotShifts`. Short-circuits
// the slotStart=0 case and cells with nothing to shift.
function shiftedCell(cell, slotStart) {
  if (!cell || slotStart === 0) return cell;
  if (!cell.decisionTimes || cell.decisionTimes.length === 0) return cell;
  if (!cell.slotShifts) cell.slotShifts = {};
  if (!cell.slotShifts[slotStart]) {
    cell.slotShifts[slotStart] = shiftCell(cell, slotStart);
  }
  return cell.slotShifts[slotStart];
}

// onSlotStartChange is the central handler for slot_start picker clicks
// on the Conditions section. Updates state and re-renders every view
// that derives from slot_start: heatmap cell colors + the Normal
// operations chart. Per-collapsible slot_start pickers route through
// their own state (collapsibleState[name].slotStart) and re-render
// only their section.
function onSlotStartChange(newSlot) {
  if (newSlot === selectedSlotStart) return;
  selectedSlotStart = newSlot;
  const data = window.REPORT_DATA;
  // Re-render heatmap section in place so cell colors reflect the new
  // slot_start. The Conditions section's picker rebuilds via its own
  // renderConditionsSection re-mount below.
  const oldOverview = document.getElementById('overview');
  if (oldOverview) {
    oldOverview.replaceWith(renderHeatmap(data));
  }
  // Re-render Conditions section so the slot_start picker's active
  // button updates and the chart redraws.
  const oldCond = document.getElementById('conditions');
  if (oldCond) {
    oldCond.replaceWith(renderConditionsSection(data));
  }
}

// onTrendMetricChange handles the y-axis-metric toggle for multi-point
// sweep tabs. Only the modal's active tab needs re-rendering — the
// heatmap is unaffected (it's always keyed to success rate).
function onTrendMetricChange(newMetric) {
  if (newMetric === selectedTrendMetric) return;
  selectedTrendMetric = newMetric;
  rerenderActiveModalTab();
}

// ---- Normal operations (Conditions) section -----------------------
//
// The Conditions section is the always-visible primary CDF chart at the
// top of the page. It shows the currently-selected scenario's CDF at
// the picker-chosen (K, BTT, σ, slot_start). Heatmap row click updates
// the selected scenario; pickers update K/BTT/σ/slot_start.
//
// Data source for Phase 1: p2p_ideal (σ=0.1) OR p2p_normal (σ=0.5) —
// whichever matches `selectedSigma`. Phase 2 will collapse these into
// a single p2p_baseline sweep with multi-axis (K × BTT × σ) points.

// findBaselineSweepPoint returns {sweep, point} matching the current
// K / BTT / σ selection, or null if no point matches. Phase 1 picks
// p2p_ideal / p2p_normal by σ; Phase 2 will look up by (K, BTT, σ)
// tuple in a unified p2p_baseline sweep.
function findBaselineSweepPoint(data) {
  if (!data) return null;
  // Prefer the Phase-2 unified sweep when it exists.
  let sweep = data.sweeps.find((s) => s.name === 'p2p_baseline');
  if (sweep) {
    for (const pt of sweep.points) {
      const c = pt.config && pt.config.Base;
      if (!c) continue;
      const bttMs = Math.round(c.BTT / 1e6);
      // σ pulled from the sweep point's per-point label or config;
      // matching by approximate float equality.
      const sigma = sweepPointSigma(sweep, pt);
      if (
        c.K === selectedK &&
        bttMs === selectedBTT &&
        Math.abs(sigma - selectedSigma) < 1e-6
      ) {
        return { sweep, point: pt };
      }
    }
    return null;
  }
  // Phase 1 fallback: σ=0.1 → p2p_ideal, σ=0.5 → p2p_normal.
  if (Math.abs(selectedSigma - 0.1) < 1e-6) {
    sweep = data.sweeps.find((s) => s.name === 'p2p_ideal');
  } else {
    sweep = data.sweeps.find((s) => s.name === 'p2p_normal');
  }
  if (!sweep || sweep.points.length === 0) return null;
  return { sweep, point: sweep.points[0] };
}

// sweepPointSigma extracts σ from the point's config/label/sweep name.
// Phase 2 baseline points will encode it explicitly in their label.
function sweepPointSigma(sweep, point) {
  if (point && point.label) {
    const m = /σ\s*=\s*(\d+(?:\.\d+)?)/.exec(point.label);
    if (m) return parseFloat(m[1]);
  }
  if (sweep.name === 'p2p_ideal') return 0.1;
  if (sweep.name === 'p2p_normal') return 0.5;
  return 0.5;
}

// Picker dimensions actually present in the loaded data. Used to
// populate K/BTT/σ button sets — buttons only appear for values
// backed by data, so Phase 1 sees single-value pickers and Phase 2
// sees the full cross-product.
function availableBaselineDimensions(data) {
  const Kset = new Set();
  const BTTset = new Set();
  const sigmaSet = new Set();
  const sweeps = ['p2p_baseline', 'p2p_normal', 'p2p_ideal'];
  for (const name of sweeps) {
    const sw = data.sweeps.find((s) => s.name === name);
    if (!sw) continue;
    for (const pt of sw.points) {
      const cfg = pt.config && pt.config.Base;
      if (!cfg) continue;
      if (typeof cfg.K === 'number' && cfg.K > 0) Kset.add(cfg.K);
      if (typeof cfg.BTT === 'number') BTTset.add(Math.round(cfg.BTT / 1e6));
      sigmaSet.add(sweepPointSigma(sw, pt));
    }
  }
  return {
    Ks: [...Kset].sort((a, b) => a - b),
    BTTs: [...BTTset].sort((a, b) => a - b),
    Sigmas: [...sigmaSet].sort((a, b) => a - b),
  };
}

// buildBaselinePicker renders a labeled button group for one picker
// dimension (K, BTT, or σ). Buttons mirror buildSlotPicker styling.
function buildBaselinePicker(label, values, suffix, getValue, setValue) {
  const picker = h('div', { class: 'sm-slot-picker' });
  picker.appendChild(h('span', { class: 'sm-slot-picker-label' }, label));
  values.forEach((v) => {
    const cur = getValue();
    const active = Math.abs(v - cur) < 1e-6;
    const btn = h(
      'button',
      {
        type: 'button',
        class: 'sm-slot-btn' + (active ? ' active' : ''),
      },
      String(v) + (suffix || ''),
    );
    btn.addEventListener('click', () => setValue(v));
    picker.appendChild(btn);
  });
  return picker;
}

// renderConditionsSection builds the always-visible "Normal operations"
// chart at the top of the page.
function renderConditionsSection(data) {
  const sec = h('section', { class: 'conditions', id: 'conditions' });

  const head = h('div', { class: 'conditions-head' });
  head.appendChild(h('h2', {}, 'Normal operations'));
  sec.appendChild(head);

  // Pickers row: K, BTT, σ, slot_start.
  const dims = availableBaselineDimensions(data);
  const pickers = h('div', { class: 'sm-controls conditions-pickers' });
  pickers.appendChild(
    buildBaselinePicker('K:', dims.Ks.length ? dims.Ks : [selectedK], null,
      () => selectedK,
      (v) => { selectedK = v; onConditionsChange(); }),
  );
  pickers.appendChild(
    buildBaselinePicker('BTT:', dims.BTTs.length ? dims.BTTs : [selectedBTT], ' ms',
      () => selectedBTT,
      (v) => { selectedBTT = v; onConditionsChange(); }),
  );
  pickers.appendChild(
    buildBaselinePicker('σ:', dims.Sigmas.length ? dims.Sigmas : [selectedSigma], null,
      () => selectedSigma,
      (v) => { selectedSigma = v; onConditionsChange(); }),
  );
  pickers.appendChild(buildSlotPicker());
  sec.appendChild(pickers);

  // Top strip: description + legend (legend gets right-aligned via
  // margin-left:auto, mirroring the modal layout).
  const top = h('div', { class: 'sm-content-top' });
  const desc = h('p', { class: 'desc conditions-desc' });
  top.appendChild(desc);
  const legendSlot = h('div', { id: 'conditions-legend-slot' });
  top.appendChild(legendSlot);
  sec.appendChild(top);

  // Chart canvas.
  const wrap = h('div', { class: 'sm-chart-wrap' });
  const canvas = h('canvas', { id: 'conditions-chart-canvas' });
  wrap.appendChild(canvas);
  sec.appendChild(wrap);

  // Chart.js needs the canvas to be in the live DOM (with computed
  // dimensions) before construction, so defer the build to the next
  // microtask after this section is mounted by main()/onConditionsChange.
  Promise.resolve().then(() => rebuildConditionsChart(data));
  return sec;
}

// onConditionsChange — picker click handler. Re-renders the heatmap
// (cell colors reflect the new K/BTT/σ) and the conditions chart.
function onConditionsChange() {
  const data = window.REPORT_DATA;
  // Re-render heatmap so cell colors track the new (K, BTT, σ).
  const oldOverview = document.getElementById('overview');
  if (oldOverview) {
    oldOverview.replaceWith(renderHeatmap(data));
  }
  // Re-render conditions section (pickers + chart) in place.
  const oldCond = document.getElementById('conditions');
  if (oldCond) {
    oldCond.replaceWith(renderConditionsSection(data));
  }
}

// rebuildConditionsChart re-draws the Normal operations CDF for the
// currently-selected scenario at the current K/BTT/σ/slot_start.
function rebuildConditionsChart(data) {
  const canvas = document.getElementById('conditions-chart-canvas');
  if (!canvas) return;
  destroyCurrentChart();

  const match = findBaselineSweepPoint(data);
  const scenario = data.scenarios.find((s) => s.name === selectedScenario);
  if (!match || !scenario) return;

  // Build the description: scenario title in bold + optional note text.
  // Avoid <strong> here because `.desc strong` carries a chip/badge
  // style that would wrap the title in a button-like box.
  const desc = document.querySelector('.conditions-desc');
  if (desc) {
    const scenTitle = scenario.title || scenario.name;
    desc.innerHTML = '';
    const titleSpan = h('span', { class: 'conditions-desc-title' }, scenTitle);
    desc.appendChild(titleSpan);
    if (scenario.note) {
      desc.appendChild(document.createTextNode(' — ' + scenario.note));
    }
  }

  // Build the legend (per-protocol chip + p99) for this point.
  const legendSlot = document.getElementById('conditions-legend-slot');
  if (legendSlot) {
    legendSlot.innerHTML = '';
    // Build a "fake sweep" with just this point so buildSweepLegend
    // sees a single-point sweep (which is what the Conditions chart
    // semantically is).
    const onePtSweep = { ...match.sweep, points: [match.point] };
    legendSlot.appendChild(buildSweepLegend(onePtSweep, scenario, data.protocols));
  }

  // Build the chart. Single-point sweep → CDF (buildLatencyChart).
  const onePtSweep = { ...match.sweep, points: [match.point] };
  currentChart = buildLatencyChart(canvas, onePtSweep, data.protocols, scenario);
}

// renderCollapsibles builds the collapsible sections below the heatmap
// — one per multi-point sweep (Increasing BTT, Heavy-tail, Stochastic
// loss, Correlated link delays, Correlated node slowness). Each section
// has its OWN pickers + y-axis toggle (collapsibleState[sweepName]).
// Default collapsed.
function renderCollapsibles(data) {
  const sec = h('section', { class: 'collapsibles' });
  data.sweeps.forEach((sw) => {
    if (sw.points.length <= 1) return; // single-point sweeps go on the Conditions chart
    sec.appendChild(renderCollapsible(sw, data));
  });
  return sec;
}

// renderCollapsible builds one collapsed-by-default chart section for
// a multi-point sweep. State (expanded, metric, slot_start) lives in
// collapsibleState[sweep.name] so each section is independent.
function renderCollapsible(sweep, data) {
  if (!collapsibleState[sweep.name]) {
    collapsibleState[sweep.name] = {
      expanded: false,
      metric: 'success',
      slotStart: 0,
    };
  }
  const state = collapsibleState[sweep.name];

  const wrap = h('div', { class: 'collapsible' });

  const header = h('button', { type: 'button', class: 'collapsible-header' });
  const arrow = h('span', { class: 'collapsible-arrow' }, state.expanded ? '▾' : '▸');
  header.appendChild(arrow);
  header.appendChild(h('span', { class: 'collapsible-title' }, sweep.title || sweep.name));
  wrap.appendChild(header);

  const body = h('div', { class: 'collapsible-body' + (state.expanded ? '' : ' collapsed') });
  wrap.appendChild(body);

  header.addEventListener('click', () => {
    state.expanded = !state.expanded;
    arrow.textContent = state.expanded ? '▾' : '▸';
    body.classList.toggle('collapsed', !state.expanded);
    if (state.expanded && !body.dataset.rendered) {
      renderCollapsibleBody(body, sweep, data, state);
      body.dataset.rendered = '1';
    }
  });

  // Lazy-render the chart only when first expanded — saves work on
  // page load when most sections stay collapsed.
  if (state.expanded) {
    renderCollapsibleBody(body, sweep, data, state);
    body.dataset.rendered = '1';
  }
  return wrap;
}

// renderCollapsibleBody fills a collapsible section with description +
// per-section pickers (slot_start + y-axis toggle) + chart.
function renderCollapsibleBody(body, sweep, data, state) {
  body.innerHTML = '';
  if (sweep.description) {
    const desc = h('p', { class: 'desc' });
    desc.textContent = sweep.description;
    body.appendChild(desc);
  }

  // Section-local pickers. slot_start picker reuses the global
  // selectedSlotStart for now — could be local-only later if cross-
  // section comparability is unwanted.
  const controls = h('div', { class: 'sm-controls collapsible-controls' });
  controls.appendChild(buildLocalSlotPicker(state, () => {
    renderCollapsibleBody(body, sweep, data, state);
  }));
  controls.appendChild(buildLocalMetricToggle(state, () => {
    renderCollapsibleBody(body, sweep, data, state);
  }));
  body.appendChild(controls);

  // Legend.
  const scenario = data.scenarios.find((s) => s.name === selectedScenario) || data.scenarios[0];
  if (scenario) {
    const top = h('div', { class: 'sm-content-top' });
    top.appendChild(buildSweepLegend(sweep, scenario, data.protocols));
    body.appendChild(top);
  }

  // Chart canvas.
  const wrap = h('div', { class: 'sm-chart-wrap' });
  const canvas = h('canvas');
  wrap.appendChild(canvas);
  body.appendChild(wrap);

  if (scenario) {
    // Each collapsible has its OWN slot_start + metric state. We
    // temporarily swap module state, build the chart, then restore —
    // a small hack to reuse the existing buildTrendLineChart helper
    // which reads module state directly.
    const savedSlot = selectedSlotStart;
    const savedMetric = selectedTrendMetric;
    selectedSlotStart = state.slotStart;
    selectedTrendMetric = state.metric;
    try {
      buildTrendLineChart(canvas, sweep, data.protocols, scenario);
    } finally {
      selectedSlotStart = savedSlot;
      selectedTrendMetric = savedMetric;
    }
  }
}

// buildLocalSlotPicker / buildLocalMetricToggle — picker variants that
// drive the per-collapsible state instead of the module-level globals.
function buildLocalSlotPicker(state, onChange) {
  const picker = h('div', { class: 'sm-slot-picker' });
  picker.appendChild(h('span', { class: 'sm-slot-picker-label' }, 'slot_start:'));
  SLOT_STARTS.forEach((s) => {
    const active = s === state.slotStart;
    const btn = h(
      'button',
      { type: 'button', class: 'sm-slot-btn' + (active ? ' active' : '') },
      `${s} ms`,
    );
    btn.addEventListener('click', () => {
      if (state.slotStart === s) return;
      state.slotStart = s;
      onChange();
    });
    picker.appendChild(btn);
  });
  return picker;
}

function buildLocalMetricToggle(state, onChange) {
  const picker = h('div', { class: 'sm-slot-picker' });
  picker.appendChild(h('span', { class: 'sm-slot-picker-label' }, 'y-axis:'));
  const options = [
    { value: 'success', label: 'success rate' },
    { value: 'p99', label: 'p99 decision time' },
  ];
  options.forEach((opt) => {
    const active = opt.value === state.metric;
    const btn = h(
      'button',
      { type: 'button', class: 'sm-slot-btn' + (active ? ' active' : '') },
      opt.label,
    );
    btn.addEventListener('click', () => {
      if (state.metric === opt.value) return;
      state.metric = opt.value;
      onChange();
    });
    picker.appendChild(btn);
  });
  return picker;
}

// rerenderActiveModalTab rebuilds the modal's currently-active tab in
// place. Scenario + active sweep are tracked on the dialog (via dataset)
// and the active .sm-tab respectively. No-op when the modal is closed.
function rerenderActiveModalTab() {
  const dlg = document.getElementById('scenario-dialog');
  if (!dlg || !dlg.open) return;
  const data = window.REPORT_DATA;
  const scenario = data.scenarios.find((s) => s.name === dlg.dataset.scenario);
  const tab = dlg.querySelector('.sm-tab.active');
  if (!scenario || !tab) return;
  const sweep = data.sweeps.find((s) => s.name === tab.getAttribute('data-sweep'));
  if (sweep) selectSweepTab(dlg, scenario, sweep);
}

// applyChartDefaults tweaks Chart.js globally so individual chart configs
// stay short.
function applyChartDefaults() {
  if (typeof Chart === 'undefined') return;
  Chart.defaults.font.family = '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
  Chart.defaults.font.size = 12;
  Chart.defaults.color = '#475569';
  Chart.defaults.borderColor = 'rgba(15, 23, 42, 0.06)';
  Chart.defaults.elements.line.tension = 0.15;
  Chart.defaults.elements.line.borderWidth = 2.5;
  Chart.defaults.elements.point.radius = 4;
  Chart.defaults.elements.point.hoverRadius = 7;
  Chart.defaults.plugins.tooltip.padding = 10;
  Chart.defaults.plugins.tooltip.cornerRadius = 6;
  Chart.defaults.plugins.tooltip.backgroundColor = 'rgba(15, 23, 42, 0.92)';
  Chart.defaults.plugins.tooltip.titleFont = { size: 12, weight: '600' };
  Chart.defaults.plugins.tooltip.bodyFont = { size: 12 };
  Chart.defaults.plugins.tooltip.boxPadding = 6;
  Chart.defaults.plugins.legend.labels.boxWidth = 12;
  Chart.defaults.plugins.legend.labels.font = { size: 12 };
}

// ---- heatmap overview ------------------------------------------------

// renderHeatmap draws the page's only persistent section: a grid of
// scenario rows × protocol columns colored by p2p_normal-sweep success
// rate (the production-shaped baseline). Each Scenario.Group becomes its
// own card so groups read as visually distinct chunks rather than rows
// in one wall of data. Clicking a cell opens the per-scenario modal.
function renderHeatmap(data) {
  const baseline = data.sweeps.find((s) => s.name === 'p2p_normal');
  if (!baseline || baseline.points.length === 0) return null;
  const point = baseline.points[0];

  const section = h('section', { class: 'heatmap', id: 'overview' });
  // --hcols drives the shared grid template (column-header row + every
  // .hrow inside every card). Keeping one CSS var means cards always
  // align horizontally with the column-header bar.
  section.style.setProperty('--hcols', String(data.protocols.length));

  // No h2 — the page's titular chart is "Normal operations" above.
  // Subtitle just names the cluster setup; K/BTT/σ/slot_start live in
  // the Conditions section's pickers and drive these cell colors too.
  const head = h('div', { class: 'heatmap-head' });
  head.appendChild(
    h('p', { class: 'desc' }, 'SSV proposer duty at n=4'),
  );
  section.appendChild(head);

  // Shared column-header bar — sits above every group card. Empty
  // top-left placeholder lines up with the scenario-name column.
  const cols = h('div', { class: 'heatmap-cols' });
  cols.appendChild(h('div', { class: 'col-head scen' }));
  data.protocols.forEach((p) => cols.appendChild(h('div', { class: 'col-head' }, p)));
  section.appendChild(cols);

  // Bucket scenarios by group, preserving catalog order.
  const groups = new Map();
  const order = [];
  data.scenarios.forEach((sc) => {
    const g = sc.group || 'Other';
    if (!groups.has(g)) {
      groups.set(g, []);
      order.push(g);
    }
    groups.get(g).push(sc);
  });

  order.forEach((g) => {
    const card = h('div', { class: 'heatmap-group' });
    card.appendChild(h('h3', { class: 'heatmap-group-label' }, g));
    const rows = h('div', { class: 'heatmap-rows' });
    groups.get(g).forEach((sc) => {
      const rowClass = sc.adversarial ? 'hrow adversarial' : 'hrow';
      const row = h('div', { class: rowClass, 'data-scenario': sc.name });
      row.appendChild(h('div', { class: 'hname' }, sc.title || sc.name));
      let hasData = false;
      data.protocols.forEach((p) => {
        const cell = findCell(point, sc.name, p);
        if (cell && cell.iterations > 0) hasData = true;
        row.appendChild(renderHeatmapCell(cell, sc));
      });
      // Row-level click handler: clicking a row updates the Normal
      // operations chart at the top of the page (no modal). Rows
      // whose cells are all n/a stay non-interactive.
      if (hasData) {
        row.classList.add('clickable');
        row.addEventListener('click', () => {
          selectHeatmapRow(row);
          selectedScenario = sc.name;
          rebuildConditionsChart(data);
        });
      }
      rows.appendChild(row);
    });
    card.appendChild(rows);
    section.appendChild(card);
  });

  return section;
}

// rateToHue maps a success rate to a chart-friendly hue:
//   rate ≤ 80% → red (hue 0)
//   rate = 90% → warm yellow (hue 50, biased away from green)
//   rate = 100% → green (hue 120)
// Two-segment ramp: 80→90% spends a wider hue range on the red→yellow
// transition so 90% reads as actually-yellow rather than yellow-green.
function rateToHue(rate) {
  if (rate <= 0.8) return 0;
  if (rate >= 1.0) return 120;
  if (rate <= 0.9) return Math.round((rate - 0.8) * 500); // 80%→0, 90%→50
  return Math.round(50 + (rate - 0.9) * 700); // 90%→50, 100%→120
}

// renderHeatmapCell colors a single cell by success rate via rateToHue.
// n/a cells (iterations=0) render grey. The row carries the click
// handler; cells just visualize per-protocol values. successRate / p99
// reflect the active slot_start via shiftedCell.
function renderHeatmapCell(cell, scenario) {
  if (!cell || cell.iterations === 0) {
    return h(
      'div',
      {
        class: 'hcell na',
        title: `n/a — scenario doesn't apply to this protocol`,
      },
      'n/a',
    );
  }
  const shifted = shiftedCell(cell, selectedSlotStart);
  const rate = shifted.successRate;
  const hue = rateToHue(rate);
  const pct = Math.round(rate * 100);
  const p99 = shifted.decisionTime ? `${Math.round(shifted.decisionTime.p99)} ms p99` : 'no decisions';
  return h(
    'div',
    {
      class: 'hcell',
      style: `--hue: ${hue}`,
      title: `${scenario.title || scenario.name} · ${cell.protocol}\n${pct}% success · ${p99}\nClick to drill in`,
    },
    `${pct}%`,
  );
}

// selectHeatmapRow visually marks the row containing `el` as selected,
// clearing any previous selection. Provides "you're looking at this one"
// feedback that persists after the modal is dismissed.
function selectHeatmapRow(el) {
  const section = el.closest('section.heatmap');
  if (!section) return;
  section.querySelectorAll('.hrow.selected').forEach((r) => r.classList.remove('selected'));
  const row = el.closest('.hrow');
  if (row) row.classList.add('selected');
}

// ---- scenario modal --------------------------------------------------
//
// One <dialog> element is cached across opens. Each open rebuilds the
// content (cheap; ≤ 4 tabs and 1 chart). Tab clicks rebuild the content
// area in place rather than maintaining 4 hidden charts — keeps memory
// usage flat and avoids the Chart.js "hidden canvas → 0 dims" foot-gun.

// currentChart is the live Chart.js instance shown in the modal, or null
// when the modal is closed (or between renders). Tracked so we can
// destroy it before swapping tabs / closing the modal.
let currentChart = null;

function destroyCurrentChart() {
  if (currentChart) {
    currentChart.destroy();
    currentChart = null;
  }
}

function closeScenarioModal(dlg) {
  destroyCurrentChart();
  dlg.close();
}

function openScenarioModal(scenario) {
  const data = window.REPORT_DATA;
  if (!data) return;

  let dlg = document.getElementById('scenario-dialog');
  if (!dlg) {
    dlg = h('dialog', { id: 'scenario-dialog', class: 'scenario-modal' });
    document.body.appendChild(dlg);
    // Backdrop click closes (clicks inside the dialog target inner
    // elements, not dlg itself).
    dlg.addEventListener('click', (ev) => {
      if (ev.target === dlg) closeScenarioModal(dlg);
    });
    // ESC-key closes the modal natively; `cancel` fires before close.
    // We also tear down the chart on `close` so cases not covered by
    // closeScenarioModal (ESC, future programmatic closers) are safe.
    dlg.addEventListener('close', destroyCurrentChart);
    dlg.addEventListener('cancel', destroyCurrentChart);
  }
  dlg.innerHTML = '';
  // Track which scenario the modal is showing so onSlotStartChange can
  // re-render the modal chart in place when the picker is clicked.
  dlg.dataset.scenario = scenario.name;

  // Header — scenario title + identifiers + close button.
  const head = h('header', { class: 'sm-head' });
  head.appendChild(h('h2', {}, scenario.title || scenario.name));
  const closeBtn = h('button', { type: 'button', class: 'sm-close', 'aria-label': 'Close' }, '×');
  closeBtn.addEventListener('click', () => closeScenarioModal(dlg));
  head.appendChild(closeBtn);
  dlg.appendChild(head);

  const body = h('div', { class: 'sm-body' });

  // Tab bar — one tab per sweep, in catalog order. p2p_ideal first.
  // Prefixed with a "p2p network:" label since every sweep dimension
  // (BTT, heavy-tail, loss, correlated delays) is a network-layer knob.
  const tabs = h('div', { class: 'sm-tabs', role: 'tablist' });
  tabs.appendChild(h('span', { class: 'sm-tabs-label' }, 'p2p network:'));
  data.sweeps.forEach((sw) => {
    const tab = h(
      'button',
      {
        type: 'button',
        class: 'sm-tab',
        role: 'tab',
        'data-sweep': sw.name,
      },
      sw.title || sw.name,
    );
    tab.addEventListener('click', () => selectSweepTab(dlg, scenario, sw));
    tabs.appendChild(tab);
  });
  body.appendChild(tabs);

  // Content area — swapped on every tab click.
  body.appendChild(h('div', { class: 'sm-content' }));
  dlg.appendChild(body);

  dlg.showModal();
  // Default to p2p_normal — matches what the heatmap colors are derived
  // from. Falls back to the first sweep if p2p_normal isn't present
  // (defensive against custom sweep lists).
  const defaultSweep = data.sweeps.find((s) => s.name === 'p2p_normal') || data.sweeps[0];
  selectSweepTab(dlg, scenario, defaultSweep);
}

// selectSweepTab activates the tab for `sweep` and rebuilds the content
// area: sweep description (if any), per-protocol summary, and the chart
// (CDF for single-point sweeps, P99 trend line for multi-point).
function selectSweepTab(dlg, scenario, sweep) {
  const data = window.REPORT_DATA;
  if (!data) return;

  dlg.querySelectorAll('.sm-tab').forEach((t) => {
    t.classList.toggle('active', t.getAttribute('data-sweep') === sweep.name);
  });

  const content = dlg.querySelector('.sm-content');
  if (!content) return;
  content.innerHTML = '';

  // Top strip: description on the left, per-protocol legend pinned to
  // the top-right. Legend uses `margin-left: auto` so it stays right-
  // aligned even when there's no description.
  const top = h('div', { class: 'sm-content-top' });
  if (sweep.description) {
    const desc = h('p', { class: 'desc' });
    desc.innerHTML = formatDescription(sweep.description);
    top.appendChild(desc);
  }
  top.appendChild(buildSweepLegend(sweep, scenario, data.protocols));
  content.appendChild(top);

  // Controls row: slot_start picker on every tab; multi-point tabs also
  // get the y-axis metric toggle (success rate ↔ p99 decision time).
  // selectedSlotStart + selectedTrendMetric are module state, kept in
  // sync with the page-header picker (slot_start) and persistent across
  // tab switches.
  const controls = h('div', { class: 'sm-controls' });
  controls.appendChild(buildSlotPicker());
  if (sweep.points.length > 1) {
    controls.appendChild(buildMetricToggle());
  }
  content.appendChild(controls);

  const wrap = h('div', { class: 'sm-chart-wrap' });
  const canvas = h('canvas');
  wrap.appendChild(canvas);
  content.appendChild(wrap);

  destroyCurrentChart();
  currentChart = buildSweepChart(canvas, sweep, scenario, data.protocols);
}

// buildSlotPicker renders the six-value slot_start picker. Used at both
// the page-header level (affects heatmap colors) and inside the modal
// (affects the open scenario's chart + legend). Both instances share
// `selectedSlotStart` and route clicks through `onSlotStartChange`,
// which handles re-rendering the heatmap + (if open) the modal.
function buildSlotPicker() {
  const picker = h('div', { class: 'sm-slot-picker' });
  picker.appendChild(h('span', { class: 'sm-slot-picker-label' }, 'slot_start:'));
  SLOT_STARTS.forEach((slotStart) => {
    const btn = h(
      'button',
      {
        type: 'button',
        class: 'sm-slot-btn' + (slotStart === selectedSlotStart ? ' active' : ''),
      },
      `${slotStart} ms`,
    );
    btn.addEventListener('click', () => onSlotStartChange(slotStart));
    picker.appendChild(btn);
  });
  return picker;
}

// buildMetricToggle renders a two-option segmented control that flips
// the multi-point trend chart's y-axis between success rate and p99
// decision time. Visually mirrors buildSlotPicker so both controls read
// as one row of sibling pickers.
function buildMetricToggle() {
  const picker = h('div', { class: 'sm-slot-picker' });
  picker.appendChild(h('span', { class: 'sm-slot-picker-label' }, 'y-axis:'));
  const options = [
    { value: 'success', label: 'success rate' },
    { value: 'p99', label: 'p99 decision time' },
  ];
  options.forEach((opt) => {
    const btn = h(
      'button',
      {
        type: 'button',
        class: 'sm-slot-btn' + (opt.value === selectedTrendMetric ? ' active' : ''),
      },
      opt.label,
    );
    btn.addEventListener('click', () => onTrendMetricChange(opt.value));
    picker.appendChild(btn);
  });
  return picker;
}

// shiftCell returns a slot-start-adjusted view of `cell` in absolute
// slot time (chart x = when in the slot the decision lands).
// Protocol-aware:
//   QBFT — pipeline runs slot_start later → sample plots at
//     decide_time + slot_start. Sample fails when the shifted value
//     overflows SLOT_END_MS.
//   OBFT / 2abOBFT — broadcast schedule is slot-anchored → sample
//     plots at T_k_broadcast unchanged. Sample fails when T_k <
//     slot_start (broadcast fired before operator joined).
// successRate, decisionTimes, and decisionTime are recomputed from
// surviving samples; other fields (bandwidth, miss reasons) carry
// through unchanged. Pure — never mutates the input.
function shiftCell(cell, slotStart) {
  if (!cell || cell.iterations === 0 || slotStart === 0) return cell;
  const samples = cell.decisionTimes || [];
  const adjusted = [];
  const isQBFT = cell.protocol === 'QBFT';
  for (let i = 0; i < samples.length; i++) {
    const t = samples[i];
    if (isQBFT) {
      const shifted = t + slotStart;
      if (shifted <= SLOT_END_MS) adjusted.push(shifted);
    } else {
      if (t >= slotStart) adjusted.push(t);
    }
  }
  let decisionTime = null;
  if (adjusted.length > 0) {
    decisionTime = {
      p50: percentileOf(adjusted, 50),
      p90: percentileOf(adjusted, 90),
      p99: percentileOf(adjusted, 99),
      mean: adjusted.reduce((a, b) => a + b, 0) / adjusted.length,
    };
  }
  return Object.assign({}, cell, {
    decisionTimes: adjusted,
    successRate: adjusted.length / cell.iterations,
    decisionTime,
  });
}

// percentileOf computes the p-th percentile of a sorted-ascending array
// using linear interpolation. Matches the Go-side
// Distribution.Percentile formula (position = (p/100) * (N-1), interp
// between floor and ceil) so legend p99 values for shifted samples stay
// consistent with the unshifted case (which uses Go-computed percentiles).
function percentileOf(sortedArr, p) {
  const N = sortedArr.length;
  if (N === 0) return 0;
  if (p <= 0) return sortedArr[0];
  if (p >= 100) return sortedArr[N - 1];
  const pos = (p / 100) * (N - 1);
  const lo = Math.floor(pos);
  const hi = Math.ceil(pos);
  if (lo === hi) return sortedArr[lo];
  const frac = pos - lo;
  return sortedArr[lo] + frac * (sortedArr[hi] - sortedArr[lo]);
}

// protocolStats returns success-rate and P99 ranges for `protocol` across
// the sweep's points, or null when the scenario doesn't apply at any
// point. Used by buildSweepLegend to render the colored per-protocol
// summary rows above each chart. Every sweep — single- or multi-point —
// sees the slot_start-shifted view of each cell.
function protocolStats(sweep, scenario, protocol) {
  const cells = sweep.points
    .map((pt) => shiftedCell(findCell(pt, scenario.name, protocol), selectedSlotStart))
    .filter((c) => c && c.iterations > 0);
  if (cells.length === 0) return null;
  const successes = cells.map((c) => c.successRate);
  const p99s = cells
    .map((c) => (c.decisionTime ? c.decisionTime.p99 : null))
    .filter((v) => v !== null);
  return {
    successMin: Math.min(...successes),
    successMax: Math.max(...successes),
    p99Min: p99s.length > 0 ? Math.min(...p99s) : null,
    p99Max: p99s.length > 0 ? Math.max(...p99s) : null,
  };
}

// buildSweepLegend renders one row per protocol: colored swatch + name +
// success-rate chip (hue-tinted by the worst-case rate via rateToHue,
// matching the heatmap gradient) + p99 (range when the sweep is
// multi-point). Replaces Chart.js's built-in legend, which is disabled
// in the chart options.
//
// Every row contributes exactly five children (swatch, name, chip, sep,
// p99) so the parent grid keeps columns aligned across rows; n/a rows
// emit empty placeholders for the missing sep/p99 slots.
function buildSweepLegend(sweep, scenario, protocols) {
  const legend = h('div', { class: 'sm-legend' });
  protocols.forEach((p) => {
    const row = h('div', { class: 'sm-legend-item' });
    row.appendChild(
      h('span', { class: 'sm-legend-swatch', style: `background: ${protocolColor(p)}` }),
    );
    row.appendChild(h('span', { class: 'sm-legend-name' }, p));
    const stats = protocolStats(sweep, scenario, p);
    if (!stats) {
      row.appendChild(h('span', { class: 'sm-legend-pct na' }, 'n/a'));
      row.appendChild(h('span', { class: 'sm-legend-sep' }));
      row.appendChild(h('span', { class: 'sm-legend-p99' }));
      legend.appendChild(row);
      return;
    }
    // Color the chip by the worst-case (min) rate so a sweep that dips
    // below 80% reads as red even if other points are green.
    const hue = rateToHue(stats.successMin);
    const sMin = (stats.successMin * 100).toFixed(2);
    const sMax = (stats.successMax * 100).toFixed(2);
    const sStr = sMin === sMax ? `${sMin}%` : `${sMin}–${sMax}%`;
    row.appendChild(
      h('span', { class: 'sm-legend-pct', style: `--hue: ${hue}` }, sStr),
    );
    if (stats.p99Min !== null) {
      const pMin = Math.round(stats.p99Min);
      const pMax = Math.round(stats.p99Max);
      const pStr = pMin === pMax ? `p99 ${pMin} ms` : `p99 ${pMin}–${pMax} ms`;
      row.appendChild(h('span', { class: 'sm-legend-sep' }, '·'));
      row.appendChild(h('span', { class: 'sm-legend-p99' }, pStr));
    } else {
      row.appendChild(h('span', { class: 'sm-legend-sep' }));
      row.appendChild(h('span', { class: 'sm-legend-p99' }));
    }
    legend.appendChild(row);
  });
  return legend;
}

// buildSweepChart returns a CDF (for a 1-point sweep) or a P99 trend
// line (for a multi-point sweep).
function buildSweepChart(canvas, sweep, scenario, protocols) {
  if (sweep.points.length === 1) {
    return buildLatencyChart(canvas, sweep, protocols, scenario);
  }
  return buildTrendLineChart(canvas, sweep, protocols, scenario);
}

// ---- CDF chart (single-point sweep) ---------------------------------
//
// Each successful sim contributes 1/Iterations to the cumulative success
// fraction at its decision time. The line steps up at every sample's
// x-coordinate and plateaus at the right edge — protocols that don't
// decide every time leave the plateau below 1.0.

function cdfPoints(sortedSamples, iterations) {
  if (!iterations) return [];
  const pts = [{ x: 0, y: 0 }];
  for (let i = 0; i < sortedSamples.length; i++) {
    const x = sortedSamples[i];
    const y = (i + 1) / iterations;
    // Collapse runs at the same integer ms (common at the P99 tail
    // where many samples cluster on the same millisecond after the
    // Go-side int(v+0.5) rounding) into a single point at the run's
    // top y. Without this, Chart.js's nearest-by-x lookup at the run's
    // x finds multiple points → duplicate tooltip rows; hovering on
    // the bottom edge of the resulting visual step also reads the
    // pre-step y instead of the cumulative value at that x.
    const last = pts[pts.length - 1];
    if (last.x === x) {
      last.y = y;
    } else {
      pts.push({ x, y });
    }
  }
  return pts;
}

function cdfChartData(sweep, protocols, scenario) {
  const point = sweep.points[0];
  return {
    datasets: protocols.map((p) => {
      const cell = shiftedCell(findCell(point, scenario.name, p), selectedSlotStart);
      const samples = (cell && cell.decisionTimes) || [];
      const iters = cell ? cell.iterations : 0;
      const pts = cdfPoints(samples, iters);
      // Mark the line's terminator (the protocol's last sample) with a
      // square; earlier points hidden. The legend chip already carries
      // the success-rate signal, so the line stops at its real end
      // rather than getting prolonged to the slot cutoff.
      const lastIdx = samples.length > 0 ? pts.length - 1 : -1;
      const radii = pts.map((_, i) => (i === lastIdx ? 7 : 0));
      const styles = pts.map((_, i) => (i === lastIdx ? 'rect' : 'circle'));
      return {
        label: p,
        borderColor: protocolColor(p),
        backgroundColor: protocolColor(p),
        // Step-before: horizontal at y_i until the next sample's x, then
        // vertical jump up at x_{i+1}. This is the left-continuous CDF
        // shape — line stays at the bottom until each new sample lifts
        // it. (Chart.js's `stepped: 'after'` is the right-continuous
        // version, which draws horizontal at the *new* y, putting the
        // line at the top for a single-jump CDF like 0→1 at x=3500.)
        stepped: 'before',
        pointRadius: radii,
        pointStyle: styles,
        pointHoverRadius: 7,
        borderWidth: 2,
        data: pts,
      };
    }),
  };
}

function buildLatencyChart(canvas, sweep, protocols, scenario) {
  return new Chart(canvas, {
    type: 'line',
    data: cdfChartData(sweep, protocols, scenario),
    plugins: [cdfZonesPlugin, cdfSlotStartPlugin],
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: false, axis: 'x' },
      scales: {
        x: {
          type: 'linear',
          title: { display: true, text: 'decision time within slot (ms)' },
          min: 0,
          max: SLOT_END_MS,
          grid: { display: false },
          ticks: { padding: 4 },
        },
        y: {
          title: { display: true, text: 'cumulative success rate' },
          min: 0,
          max: 1,
          grid: { color: 'rgba(15, 23, 42, 0.06)' },
          ticks: {
            padding: 6,
            callback: (v) => `${Math.round(v * 100)}%`,
          },
        },
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            title: (items) => (items[0] ? `${Math.round(items[0].parsed.x)} ms` : ''),
            label: (ctx) => {
              const pct = (ctx.parsed.y * 100).toFixed(2);
              return `${ctx.dataset.label}: ${pct}% finished`;
            },
          },
        },
      },
    },
  });
}

// ---- trend line chart (multi-point sweep) ---------------------------

function buildTrendLineChart(canvas, sweep, protocols, scenario) {
  const isSuccess = selectedTrendMetric !== 'p99';
  const ySuccess = {
    title: { display: true, text: 'success rate' },
    min: 0,
    max: 1,
    grid: { color: 'rgba(15, 23, 42, 0.06)' },
    ticks: { padding: 6, callback: (v) => `${Math.round(v * 100)}%` },
  };
  const yP99 = {
    title: { display: true, text: 'p99 decision time (ms)' },
    grid: { color: 'rgba(15, 23, 42, 0.06)' },
    ticks: { padding: 6 },
  };
  return new Chart(canvas, {
    type: 'line',
    data: trendLineChartData(sweep, protocols, scenario),
    plugins: isSuccess ? [cdfZonesPlugin] : [],
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: false },
      scales: {
        x: {
          title: { display: true, text: sweep.axisLabel || '' },
          grid: { display: false },
          ticks: { padding: 4 },
        },
        y: isSuccess ? ySuccess : yP99,
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            title: (items) =>
              items[0] ? `${sweep.axisLabel || 'point'}: ${items[0].label}` : '',
            label: (ctx) => {
              if (isSuccess) {
                const pct = (ctx.parsed.y * 100).toFixed(2);
                return `${ctx.dataset.label}: ${pct}% success`;
              }
              return `${ctx.dataset.label}: p99 ${Math.round(ctx.parsed.y)} ms`;
            },
          },
        },
      },
    },
  });
}

function trendLineChartData(sweep, protocols, scenario) {
  const isSuccess = selectedTrendMetric !== 'p99';
  return {
    labels: sweep.points.map((pt) => pt.label),
    datasets: protocols.map((p) => {
      const data = sweep.points.map((pt) => {
        const cell = shiftedCell(findCell(pt, scenario.name, p), selectedSlotStart);
        if (!cell || cell.iterations === 0) return null;
        if (isSuccess) return cell.successRate;
        return cell.decisionTime ? cell.decisionTime.p99 : null;
      });
      return {
        label: p,
        borderColor: protocolColor(p),
        backgroundColor: protocolColor(p),
        pointStyle: protocolPointStyle(p),
        spanGaps: true,
        fill: false,
        tension: 0.15,
        borderDash: protocolDash(p),
        data,
      };
    }),
  };
}

// ---- helpers ---------------------------------------------------------

// h(tag, attrs, ...children) — small DOM builder. attrs are setAttribute'd
// (except 'class', which sets className). Children may be strings, DOM
// nodes, or null/undefined (skipped).
function h(tag, attrs, ...children) {
  const el = document.createElement(tag);
  if (attrs) {
    Object.entries(attrs).forEach(([k, v]) => {
      if (k === 'class') el.className = v;
      else el.setAttribute(k, v);
    });
  }
  children.flat().forEach((c) => {
    if (c == null) return;
    if (typeof c === 'string' || typeof c === 'number') {
      el.appendChild(document.createTextNode(String(c)));
    } else {
      el.appendChild(c);
    }
  });
  return el;
}

function findCell(point, scenarioName, protocolName) {
  return point.cells.find((c) => c.scenario === scenarioName && c.protocol === protocolName) || null;
}

function protocolColor(name) {
  return PROTOCOL_COLORS[name] || '#888';
}

function protocolDash(name) {
  return name === 'OBFT' ? [] : [6, 4];
}

function protocolPointStyle(name) {
  switch (name) {
    case 'OBFT':
      return 'circle';
    case 'QBFT':
      return 'triangle';
    default:
      return 'rect';
  }
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (ch) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  })[ch]);
}

// formatDescription HTML-escapes the input, then wraps three families of
// tokens in <strong> for visual emphasis: set literals like {4, 7, 10},
// parameter assignments like n=4 / BTT=200ms, and known network-model
// names. Result is an HTML fragment suitable for innerHTML.
function formatDescription(text) {
  const networkModels = '(?:ConstantDelay|LogNormalDelay|LossyNetwork|PerReceiverDelay|CorrelatedLinkDelay|JitteredDelay)';
  let out = escapeHtml(text);
  const patterns = [
    /\{[^}]+\}/g,
    /\b[A-Za-z][A-Za-z_0-9]*=[A-Za-z0-9./_]+(?:ms|s)?\b/g,
    new RegExp('\\b' + networkModels + '\\b', 'g'),
  ];
  patterns.forEach((re) => {
    out = out.replace(re, (m) => `<strong>${m}</strong>`);
  });
  return out;
}
